'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { isAuthenticated } from '@/lib/auth';

export default function LoginPage() {
  const router = useRouter();
  const [isClient, setIsClient] = useState(false);
  const [loading, setLoading] = useState<string | null>(null);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setIsClient(true);

    // 이미 로그인되어 있으면 홈으로 리다이렉트
    if (isAuthenticated()) {
      router.push('/');
    }
  }, [router]);

  const handleEmailLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading('email');
    setError(null);

    const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';

    try {
      const response = await fetch(`${baseUrl}/api/login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include', // 세션 쿠키를 받기 위해 필수
        body: JSON.stringify({
          email,
          password,
        }),
      });

      const contentType = response.headers.get('content-type');

      // HTML 응답인 경우 (엔드포인트가 없는 경우)
      if (contentType?.includes('text/html')) {
        throw new Error('백엔드에 /api/login 엔드포인트가 구현되지 않았습니다.');
      }

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || '로그인에 실패했습니다.');
      }

      // 토큰 기반 인증: access_token을 localStorage에 저장
      if (data.access_token) {
        localStorage.setItem('access_token', data.access_token);

        // 사용자 정보가 함께 왔다면 저장
        if (data.user) {
          localStorage.setItem('user_data', JSON.stringify(data.user));
        }

        router.push('/');
      } else {
        throw new Error('토큰을 받지 못했습니다.');
      }
    } catch (err) {
      console.error('로그인 오류:', err);

      if (err instanceof TypeError && err.message.includes('fetch')) {
        setError(
          '백엔드 서버 연결 실패\n\n' +
          '가능한 원인:\n' +
          '1. 백엔드 서버가 실행되지 않음\n' +
          '2. /api/login 엔드포인트가 구현되지 않음\n' +
          '3. CORS 설정이 올바르지 않음\n\n' +
          'BACKEND_TODO.md 파일을 참고하여 백엔드를 설정해주세요.'
        );
      } else {
        setError(err instanceof Error ? err.message : '알 수 없는 오류가 발생했습니다.');
      }
      setLoading(null);
    }
  };

  const handleSocialLogin = async (provider: 'google' | 'naver' | 'kakao') => {
    try {
      setLoading(provider);

      // 라라벨 백엔드 OAuth 엔드포인트로 직접 리다이렉트
      const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
      const oauthUrl = `${baseUrl}/auth/${provider}`;

      console.log('=== OAuth 로그인 시작 ===');
      console.log('Provider:', provider);
      console.log('Base URL:', baseUrl);
      console.log('OAuth URL:', oauthUrl);
      console.log('환경변수 확인:', {
        NEXT_PUBLIC_API_URL: process.env.NEXT_PUBLIC_API_URL,
      });

      // 백엔드로 직접 이동 (라라벨이 OAuth provider로 리다이렉트 처리)
      window.location.href = oauthUrl;
    } catch (error) {
      console.error(`${provider} OAuth 리다이렉트 실패:`, error);
      alert('로그인 요청에 실패했습니다. 다시 시도해주세요.');
      setLoading(null);
    }
  };

  if (!isClient) {
    return null; // 서버 사이드 렌더링 방지
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="max-w-md w-full space-y-8 p-8 bg-white rounded-lg shadow-lg">
        <div className="text-center">
          <h2 className="text-3xl font-bold text-gray-900">로그인</h2>
          <p className="mt-2 text-sm text-gray-600">
            이메일 또는 소셜 계정으로 로그인하세요
          </p>
        </div>

        {/* 이메일 로그인 */}
        <form onSubmit={handleEmailLogin} className="mt-8 space-y-4">
          <div>
            <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
              이메일
            </label>
            <input
              id="email"
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              placeholder="example@email.com"
              disabled={loading !== null}
            />
          </div>
          <div>
            <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-1">
              비밀번호
            </label>
            <input
              id="password"
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              placeholder="비밀번호를 입력하세요"
              disabled={loading !== null}
            />
          </div>

          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg text-sm whitespace-pre-line">
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading !== null}
            className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-4 rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading === 'email' ? '로그인 중...' : '이메일로 로그인'}
          </button>
        </form>

        {/* 구분선 */}
        <div className="relative">
          <div className="absolute inset-0 flex items-center">
            <div className="w-full border-t border-gray-300"></div>
          </div>
          <div className="relative flex justify-center text-sm">
            <span className="px-2 bg-white text-gray-500">또는</span>
          </div>
        </div>

        <div className="space-y-4">
          {/* 구글 로그인 */}
          <button
            onClick={() => handleSocialLogin('google')}
            disabled={loading !== null}
            className="w-full flex items-center justify-center gap-3 px-4 py-3 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <svg className="w-5 h-5" viewBox="0 0 24 24">
              <path
                fill="#4285F4"
                d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
              />
              <path
                fill="#34A853"
                d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
              />
              <path
                fill="#FBBC05"
                d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
              />
              <path
                fill="#EA4335"
                d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
              />
            </svg>
            <span className="text-sm font-medium text-gray-700">
              {loading === 'google' ? '로딩 중...' : 'Google로 계속하기'}
            </span>
          </button>

          {/* 네이버 로그인 */}
          <button
            onClick={() => handleSocialLogin('naver')}
            disabled={loading !== null}
            className="w-full flex items-center justify-center gap-3 px-4 py-3 bg-[#03C75A] hover:bg-[#02b350] rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <span className="text-xl font-bold text-white">N</span>
            <span className="text-sm font-medium text-white">
              {loading === 'naver' ? '로딩 중...' : '네이버로 계속하기'}
            </span>
          </button>

          {/* 카카오 로그인 */}
          <button
            onClick={() => handleSocialLogin('kakao')}
            disabled={loading !== null}
            className="w-full flex items-center justify-center gap-3 px-4 py-3 bg-[#FEE500] hover:bg-[#fdd800] rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <svg className="w-5 h-5" viewBox="0 0 24 24">
              <path
                fill="#000000"
                d="M12 3c5.799 0 10.5 3.664 10.5 8.185 0 4.52-4.701 8.184-10.5 8.184a13.5 13.5 0 0 1-1.727-.11l-4.408 2.883c-.501.265-.678.236-.472-.413l.892-3.678c-2.88-1.46-4.785-3.99-4.785-6.866C1.5 6.665 6.201 3 12 3z"
              />
            </svg>
            <span className="text-sm font-medium text-gray-900">
              {loading === 'kakao' ? '로딩 중...' : '카카오로 계속하기'}
            </span>
          </button>
        </div>

        <div className="mt-6">
          <p className="text-xs text-center text-gray-500">
            로그인하시면 서비스 이용약관 및 개인정보 처리방침에 동의하는 것으로 간주됩니다.
          </p>
        </div>
      </div>
    </div>
  );
}
